CREATE TABLE [sales].[SalesInvoiceItems]([InvoiceItemId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SalesInvoiceItems_Id] DEFAULT NEWSEQUENTIALID(),[InvoiceId] UNIQUEIDENTIFIER NOT NULL,[ProductId] UNIQUEIDENTIFIER NOT NULL,[Barcode] NVARCHAR(100) NULL,[Quantity] DECIMAL(18,4) NOT NULL,[UnitPrice] DECIMAL(18,4) NOT NULL,[DiscountPercentage] DECIMAL(5,2) NOT NULL CONSTRAINT [DF_SalesInvoiceItems_DiscountPercent] DEFAULT 0,[DiscountAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_SalesInvoiceItems_Discount] DEFAULT 0,[TaxPercentage] DECIMAL(5,2) NOT NULL,[TaxAmount] DECIMAL(18,2) NOT NULL,[LineTotal] DECIMAL(18,2) NOT NULL,[ReturnedQuantity] DECIMAL(18,4) NOT NULL CONSTRAINT [DF_SalesInvoiceItems_Returned] DEFAULT 0,CONSTRAINT [PK_SalesInvoiceItems] PRIMARY KEY([InvoiceItemId]),CONSTRAINT [FK_SalesInvoiceItems_Invoice] FOREIGN KEY([InvoiceId]) REFERENCES [sales].[SalesInvoices]([InvoiceId]) ON DELETE CASCADE,CONSTRAINT [FK_SalesInvoiceItems_Product] FOREIGN KEY([ProductId]) REFERENCES [master].[Products]([ProductId]),CONSTRAINT [CK_SalesInvoiceItems_Quantity] CHECK([Quantity]>0 AND [ReturnedQuantity]>=0 AND [ReturnedQuantity]<=[Quantity]));
